(function(E){ const x = E["exam-08"] = E["exam-08"] || {units:{}}; (x.units = x.units || {})["x08-l1"] = {"id":"x08-l1","patterns":["L1-travel","PARA-money","PARA-time","TR-number","TR-spell","TR-selfcorrect","TR-price","TR-paraphrase"],"title":{"en":"Listening Part 1: advice on a city weekend","tr":"Listening Part 1: şehirde bir hafta sonu için tavsiye","fa":"Listening Part 1: راهنمایی برای یک آخر هفته در شهر"},"objective":{"en":"In this lesson you will learn to complete a set of notes while a friend gives advice about a trip: follow the headings, catch numbers that sound alike and details that change, and write one word or a number.","tr":"Bu derste bir arkadaş bir gezi hakkında tavsiye verirken bir not listesini tamamlamayı öğreneceksin: başlıkları takip edecek, birbirine benzeyen sayıları ve değişen bilgileri yakalayacak ve bir kelime ya da bir sayı yazacaksın.","fa":"در این درس یاد می‌گیری وقتی یک دوست درباره‌ی یک سفر راهنمایی می‌کند، یک دسته یادداشت را کامل کنی: عنوان‌ها را دنبال کنی، عددهایی را که شبیه هم‌اند و اطلاعاتی را که عوض می‌شود بگیری و یک کلمه یا یک عدد بنویسی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 1: advice on a city weekend","tr":"Listening Part 1: şehirde bir hafta sonu için tavsiye","fa":"Listening Part 1: راهنمایی برای یک آخر هفته در شهر"},"objective":{"en":"In this lesson you will learn to complete a set of notes while a friend gives advice about a trip: follow the headings, catch numbers that sound alike and details that change, and write one word or a number.","tr":"Bu derste bir arkadaş bir gezi hakkında tavsiye verirken bir not listesini tamamlamayı öğreneceksin: başlıkları takip edecek, birbirine benzeyen sayıları ve değişen bilgileri yakalayacak ve bir kelime ya da bir sayı yazacaksın.","fa":"در این درس یاد می‌گیری وقتی یک دوست درباره‌ی یک سفر راهنمایی می‌کند، یک دسته یادداشت را کامل کنی: عنوان‌ها را دنبال کنی، عددهایی را که شبیه هم‌اند و اطلاعاتی را که عوض می‌شود بگیری و یک کلمه یا یک عدد بنویسی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word / number","tr":"1 kelime / sayı","fa":"۱ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a family weekend in the city","tr":"Bu sınav: şehirde bir aile hafta sonu","fa":"این آزمون: یک آخر هفته‌ی خانوادگی در شهر"},"intro":{"en":"Part 1 is an everyday conversation in which one person needs information. Here a friend gives tips for a trip, a situation that comes up regularly. The speakers are relaxed and chatty, so the answers are hidden among stories and opinions.","tr":"Part 1, birinin bilgiye ihtiyaç duyduğu günlük bir konuşmadır. Burada bir arkadaş bir gezi için öneriler veriyor; düzenli olarak çıkan bir durum. Konuşanlar rahat ve sohbet havasındadır, bu yüzden cevaplar hikâyelerin ve görüşlerin arasında saklıdır.","fa":"Part 1 یک گفتگوی روزمره است که در آن کسی به اطلاعات نیاز دارد. این‌جا یک دوست برای یک سفر توصیه می‌کند؛ موقعیتی که مرتب می‌آید. گوینده‌ها راحت و خودمانی حرف می‌زنند، پس جواب‌ها لای قصه‌ها و نظرها پنهان‌اند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x08-l1-ctx","exam":true,"patterns":["L1-travel","PARA-money","PARA-time"],"often":{"pattern":"L1-travel","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Tips for a family weekend away","tr":"Bir aile hafta sonu gezisi için öneriler","fa":"توصیه‌هایی برای یک آخر هفته‌ی خانوادگی"},"asks":{"en":"One friend phones another who lives in a big city and asks for advice: where to stay, how to get around, and what to do with children on Saturday and Sunday. You complete one set of notes.","tr":"Bir arkadaş, büyük bir şehirde yaşayan başka bir arkadaşını arayıp tavsiye istiyor: nerede kalınır, şehirde nasıl dolaşılır, cumartesi ve pazar çocuklarla ne yapılır. Tek bir not listesini tamamlıyorsun.","fa":"یک دوست به دوست دیگرش که در یک شهر بزرگ زندگی می‌کند زنگ می‌زند و راهنمایی می‌خواهد: کجا بمانند، چطور در شهر رفت‌وآمد کنند و شنبه و یکشنبه با بچه‌ها چه کنند. یک دسته یادداشت را کامل می‌کنی."},"fields":["Where to stay","Cost per night","Getting around","Saturday","Sunday","Parking"],"words":[{"a":"accommodation","b":"where to stay / a place to sleep","tr":"konaklama","fa":"محل اقامت"},{"a":"next to","b":"right beside / just by","tr":"hemen yanında","fa":"درست کنارِ"},{"a":"a night","b":"per night / for each night","tr":"gecelik","fa":"هر شب"},{"a":"cheaper now","b":"they’ve brought it down / it’s been reduced","tr":"artık daha ucuz","fa":"الان ارزان‌تر"},{"a":"public transport","b":"the buses / the underground","tr":"toplu taşıma","fa":"حمل‌ونقل عمومی"},{"a":"a pass","b":"one ticket for all your journeys","tr":"kart, abonman bilet","fa":"کارت یا بلیت چندسفره"},{"a":"lasts","b":"it takes / it goes on for","tr":"sürer","fa":"طول می‌کشد"},{"a":"free","b":"you don’t pay / no charge","tr":"ücretsiz","fa":"رایگان"},{"a":"no need to book","b":"just turn up / walk in","tr":"rezervasyon gerekmez","fa":"رزرو لازم نیست"},{"a":"crowded","b":"packed / very busy","tr":"kalabalık","fa":"شلوغ"},{"a":"bring","b":"take with you / don’t forget","tr":"yanında getirmek","fa":"با خودت بیاوری"},{"a":"leave the car","b":"park at / drive to ... and take the bus","tr":"arabayı bırakmak","fa":"ماشین را جایی گذاشتن"}],"traps":[{"en":"Numbers that sound alike: \"thirteen\" and \"thirty\", \"nineteen\" and \"ninety\". Listen for the stress and for the speaker repeating the number another way: \"nine-zero\", \"an hour and a half\".","tr":"Birbirine benzeyen sayılar: \"thirteen\" ile \"thirty\", \"nineteen\" ile \"ninety\". Vurguya ve konuşanın sayıyı başka bir yolla tekrar etmesine kulak ver: \"nine-zero\", \"an hour and a half\".","fa":"عددهایی که شبیه هم شنیده می‌شوند: «thirteen» و «thirty»، «nineteen» و «ninety». به تکیه‌ی کلمه گوش بده و به اینکه گوینده عدد را جور دیگری تکرار می‌کند: «nine-zero»، «an hour and a half»."},{"en":"Old information is corrected: \"It said Friday on the poster, but it’s been moved to Thursday.\" Write the new detail.","tr":"Eski bilgi düzeltilir: \"Afişte cuma yazıyordu ama perşembeye alındı.\" Yeni bilgiyi yaz.","fa":"اطلاعات قدیمی اصلاح می‌شود: «روی پوستر جمعه نوشته بود، اما به پنجشنبه منتقل شد». اطلاعات جدید را بنویس."},{"en":"A popular choice is mentioned and then dismissed: \"Everyone goes to the castle, but the view from the hill is better.\" The answer is the one the speaker recommends.","tr":"Popüler bir seçenek söylenip geçilir: \"Herkes kaleye gider ama tepeden manzara daha güzel.\" Cevap konuşanın önerdiği şeydir.","fa":"یک انتخاب معروف گفته و بعد کنار گذاشته می‌شود: «همه به قلعه می‌روند، اما منظره از روی تپه بهتر است». جواب چیزی است که گوینده توصیه می‌کند."}],"example":{"lines":[["Friend","The boat trip leaves at a quarter past ten."],["Caller","Ten fifteen?"],["Friend","No, sorry, that was last year. It’s ten forty-five now."]],"item":"Boat trip: leaves at ___ am","answer":"10.45","why":{"en":"Ten fifteen was last year. The corrected time is 10.45.","tr":"Onu on beş geçen yıldı. Düzeltilmiş saat 10.45.","fa":"ده و ربع مال پارسال بود. ساعتِ اصلاح‌شده ۱۰:۴۵ است."}}},{"id":"L1-travel","ctx":["L1-travel"],"title":{"en":"A trip, a holiday or a local event","tr":"Bir gezi, bir tatil ya da yerel bir etkinlik","fa":"سفر، تعطیلات یا یک رویداد محلی"},"asks":{"en":"A caller books or asks about a trip, a holiday cottage, a festival or an excursion, or a friend gives travel advice. The notes collect places, dates, prices, what is included and what to book in advance.","tr":"Arayan bir gezi, bir tatil evi, bir festival ya da bir tur için yer ayırtır ya da bilgi alır; ya da bir arkadaş seyahat tavsiyesi verir. Notlar yerleri, tarihleri, fiyatları, nelerin dahil olduğunu ve neyin önceden ayırtılması gerektiğini toplar.","fa":"تماس‌گیرنده یک سفر، یک ویلای تعطیلات، یک جشنواره یا یک گردش را رزرو می‌کند یا درباره‌اش می‌پرسد، یا دوستی توصیه‌ی سفر می‌دهد. یادداشت‌ها جاها، تاریخ‌ها، قیمت‌ها، چیزهایی که شامل می‌شود و چیزهایی که باید از قبل رزرو کرد را جمع می‌کنند."},"fields":["Destination","Dates / length of stay","Accommodation","Price per person","What is included","Transport","Things to see or do","Tickets / booking"],"words":[{"a":"return ticket","b":"there and back","tr":"gidiş-dönüş bileti","fa":"بلیت رفت‌وبرگشت"},{"a":"included","b":"you don't pay extra for / it comes with","tr":"dahil","fa":"شامل قیمت"},{"a":"per person","b":"each / for every adult","tr":"kişi başı","fa":"برای هر نفر"},{"a":"in advance","b":"book ahead / before you go","tr":"önceden","fa":"از قبل"},{"a":"departure","b":"it leaves at / we set off","tr":"kalkış","fa":"حرکت"},{"a":"cancellation","b":"if you can't come / call it off","tr":"iptal","fa":"لغو"},{"a":"excursion","b":"a day trip to","tr":"gezi, günübirlik tur","fa":"گردش یک‌روزه"},{"a":"accommodation","b":"where you'll stay","tr":"konaklama","fa":"محل اقامت"},{"a":"sold out","b":"there are no tickets left","tr":"tükendi","fa":"تمام شده"},{"a":"half price","b":"it's fifty per cent off","tr":"yarı fiyatına","fa":"نصف قیمت"},{"a":"guided tour","b":"someone shows you round","tr":"rehberli tur","fa":"تور با راهنما"},{"a":"a fortnight","b":"two weeks","tr":"iki hafta","fa":"دو هفته"}],"traps":[{"en":"Advice from a friend: several options are listed and some are rejected. Write the one that is recommended.","tr":"Arkadaş tavsiyesi: birkaç seçenek sayılır, bazıları elenir. Tavsiye edileni yaz.","fa":"توصیه‌ی دوست: چند گزینه گفته می‌شود و بعضی رد می‌شوند. همانی را بنویس که توصیه می‌شود."},{"en":"Two times: \"the boat leaves at ten fifteen, but be there twenty minutes before\". Check which time the heading needs.","tr":"İki saat: \"tekne on on beşte kalkıyor ama yirmi dakika önce orada ol\". Başlığın hangi saati istediğine bak.","fa":"دو ساعت: «قایق ده و ربع حرکت می‌کند، ولی بیست دقیقه زودتر آنجا باش». ببین عنوان کدام ساعت را می‌خواهد."},{"en":"Included or extra: \"lunch is included, but drinks are extra\". Write the item the heading asks about.","tr":"Dahil mi, ekstra mı: \"öğle yemeği dahil ama içecekler ekstra\". Başlığın sorduğu şeyi yaz.","fa":"شامل یا اضافه: «ناهار شامل است، ولی نوشیدنی جداست». چیزی را بنویس که عنوان می‌پرسد."}],"example":{"lines":[["Friend","There’s a ferry at nine and one at eleven."],["Caller","Nine is a bit early with the children."],["Friend","The eleven o’clock is quieter anyway, and you still reach the island in time for lunch."],["Caller","Great, we’ll take that one."]],"item":"Ferry departs at: ___ a.m.","answer":"11","why":{"en":"Nine is rejected as too early. They choose the eleven o’clock ferry: write 11.","tr":"Dokuz çok erken diye eleniyor. Saat on birdeki feribotu seçiyorlar: 11 yaz.","fa":"ساعت نه چون زود است رد می‌شود. کشتیِ ساعت یازده را انتخاب می‌کنند: بنویس 11."}},"general":true,"patterns":["L1-travel"],"often":{"pattern":"L1-travel","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Ten notes, one play","tr":"On not, tek dinleme","fa":"ده یادداشت، یک بار پخش"},"body":{"en":"Questions 1-10 are one set of notes under short headings. Write ONE WORD AND/OR A NUMBER. You read the first part, listen, then get a short pause to read the rest. The answers come in the same order as the notes.","tr":"Soru 1-10, kısa başlıklar altında tek bir not listesidir. ONE WORD AND/OR A NUMBER yaz. İlk kısmı okursun, dinlersin, sonra geri kalanını okumak için kısa bir ara alırsın. Cevaplar notlarla aynı sırayla gelir.","fa":"سؤال‌های ۱ تا ۱۰ یک دسته یادداشت زیر عنوان‌های کوتاه‌اند. ONE WORD AND/OR A NUMBER بنویس. بخش اول را می‌خوانی، گوش می‌دهی و بعد یک مکث کوتاه برای خواندن بقیه داری. جواب‌ها به همان ترتیب یادداشت‌ها می‌آیند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps for notes","tr":"Notlar için dört adım","fa":"چهار قدم برای یادداشت‌ها"},"steps":[{"en":"Read the headings: they tell you which part of the plan the speakers are talking about.","tr":"Başlıkları oku: konuşanların planın hangi kısmından söz ettiğini söylerler.","fa":"عنوان‌ها را بخوان: می‌گویند گوینده‌ها درباره‌ی کدام بخش برنامه حرف می‌زنند."},{"en":"Decide what each gap needs: a price, a length of time, a name, a place or a thing.","tr":"Her boşluğun ne istediğine karar ver: fiyat, süre, isim, yer ya da eşya.","fa":"تصمیم بگیر هر جای خالی چه می‌خواهد: قیمت، مدت، اسم، مکان یا چیز."},{"en":"When a number is said, listen for it to be repeated or corrected.","tr":"Bir sayı söylendiğinde tekrarlanmasına ya da düzeltilmesine kulak ver.","fa":"وقتی عددی گفته می‌شود، گوش بده ببین تکرار یا اصلاح می‌شود یا نه."},{"en":"Write numbers as figures and copy spelled names letter by letter.","tr":"Sayıları rakamla yaz, harf harf söylenen isimleri aynen kopyala.","fa":"عددها را با رقم بنویس و اسم‌هایی را که هجی می‌شوند حرف به حرف بنویس."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Numbers that sound alike","tr":"Birbirine benzeyen sayılar","fa":"عددهایی که شبیه هم شنیده می‌شوند"},"table":{"headers":{"en":["You hear","Write"],"tr":["Duyduğun","Yaz"],"fa":["می‌شنوی","بنویس"]},"rows":[["thirTEEN (stress at the end)","13"],["THIRty (stress at the start)","30"],["fifteen... no, fifty, five-oh","50"],["an hour and a quarter","75 (minutes)"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","item":"Zoo · children under ___ go in free","lines":[["Friend","Under-fives are free, I think."],["Caller","Really? That’s good."],["Friend","Hang on, let me check the leaflet. No, it’s even better: anyone under seven gets in for nothing."]],"answer":"7","walk":[{"en":"Before you listen: the gap needs an age, so a number.","tr":"Dinlemeden önce: boşluk bir yaş istiyor, yani bir sayı.","fa":"قبل از گوش دادن: جای خالی یک سن می‌خواهد، پس یک عدد."},{"en":"\"Under-fives\" comes first, but \"hang on\" and \"no\" warn you it will change.","tr":"Önce \"under-fives\" geliyor ama \"hang on\" ve \"no\" bunun değişeceği uyarısını veriyor.","fa":"اول «under-fives» می‌آید، اما «hang on» و «no» هشدار می‌دهند که عوض می‌شود."},{"en":"\"For nothing\" = free. Write 7 as a figure.","tr":"\"For nothing\" = ücretsiz. 7’yi rakamla yaz.","fa":"«for nothing» یعنی رایگان. ۷ را با رقم بنویس."}]},"quick":{"prompt":"Notes: \"Boat hire: £___ per hour\". You hear: \"It’s fourteen pounds an hour... sorry, forty. Fourteen is for half an hour.\" What do you write?","options":["14","40","54"],"correct":1,"why":{"en":"The speaker corrects herself: forty an hour. Fourteen is the price for half an hour.","tr":"Konuşan kendini düzeltiyor: saati kırk. On dört, yarım saatin fiyatı.","fa":"گوینده حرفش را اصلاح می‌کند: ساعتی چهل. چهارده قیمت نیم ساعت است."}},"remember":{"en":"Follow the headings, wait for the final number, and write it as a figure.","tr":"Başlıkları takip et, son sayıyı bekle ve onu rakamla yaz.","fa":"عنوان‌ها را دنبال کن، منتظر عدد نهایی بمان و آن را با رقم بنویس."},"type":"explain","id":"c-x08-l1-e","course":"ielts-exams","exam":"exam-08","unit":"x08-l1"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 1","title":{"en":"A family weekend in the city","tr":"Şehirde bir aile hafta sonu","fa":"یک آخر هفته‌ی خانوادگی در شهر"},"timed":8,"ctx":["L1-travel"],"script":[{"who":"Imogen","line":"Hello?"},{"who":"Rafael","line":"Imogen, hi, it's Rafael. Have you got a few minutes? We're finally coming to visit the city next month, the whole family, and you said you'd give me some tips."},{"who":"Imogen","line":"Of course! How old are the kids now?"},{"who":"Rafael","line":"Leo's nine and Bea's six. So we need things that won't bore them."},{"who":"Imogen","line":"Right. First, where to stay. Hotels in the centre are really expensive at weekends, so I'd rent a flat. There's a nice block of holiday flats right beside the canal, about ten minutes' walk from the old town. Two bedrooms, a little kitchen, and the children can watch the boats from the window."},{"who":"Rafael","line":"Sounds perfect. Do you know what they charge?"},{"who":"Imogen","line":"When my sister stayed there in the spring it was a hundred and sixty a night. But I looked at their website yesterday, and they've brought it down for the autumn. It's a hundred and forty-five now."},{"who":"Rafael","line":"That's much better than the hotels I found. They wanted over two hundred."},{"who":"Imogen","line":"Exactly. Now, getting around. Don't bother with the car in the centre, the parking is a nightmare. Get a family pass for the buses. It covers two adults and up to three children for the whole weekend, and you can buy it on the first bus you get on."},{"who":"Rafael","line":"OK. And what should we do on Saturday?"},{"who":"Imogen","line":"There's a walking tour I always recommend. It's aimed at families, so there are stories about ghosts and smugglers, and the kids get a little map to fill in as they go."},{"who":"Rafael","line":"How long does it take? Bea's legs get tired quite quickly."},{"who":"Imogen","line":"It's ninety minutes."},{"who":"Rafael","line":"Nineteen?"},{"who":"Imogen","line":"No, ninety, nine-zero. An hour and a half. But there are plenty of stops, and it ends at a café."},{"who":"Rafael","line":"Fine. Is there a particular guide we should ask for?"},{"who":"Imogen","line":"Yes, there's one called Hal who's brilliant with children. His surname is Treharne. That's T-R-E-H-A-R-N-E."},{"who":"Rafael","line":"T-R-E-H-A-R-N-E. Got it."},{"who":"Imogen","line":"And after the tour, go to the Museum of Childhood. It's free, and on Saturdays there's a family workshop where the kids make a toy to take home. The website says it starts at two, but I think that's the winter timetable. In summer and autumn it's half past three."},{"who":"Rafael","line":"Half past three. That gives us time for lunch."},{"who":"Imogen","line":"Yes, and you won't need to book. You just turn up."},{"who":"Rafael","line":"Brilliant. Now, what about Sunday?"},{"who":"Imogen","line":"On Sunday mornings there's a food market. It's in an old bus garage near the river. It gets very crowded by eleven, so go early."},{"who":"Rafael","line":"What's good to eat there?"},{"who":"Imogen","line":"Everyone talks about the pizza van, but honestly it's nothing special. The stall the children will love is the one selling dumplings. They're filled with all sorts of things, and the kids can watch them being made."},{"who":"Rafael","line":"Dumplings. Leo will be happy. What else?"},{"who":"Imogen","line":"In the afternoon there's a kite festival in Hallam Park. It's on the second Sunday of every month in the summer and autumn, so you'll be lucky. You don't need to bring kites, they lend them out at the gate. But do bring a blanket, because the grass is often damp and you'll want to sit down."},{"who":"Rafael","line":"A blanket. OK. And can we drive there? We'll have the car with us by then, because we'll be going straight home afterwards."},{"who":"Imogen","line":"You can, but the park's own car park fills up by midday. It's easier to leave the car at the racecourse. It's free on Sundays, and there's a shuttle bus to the park gate every fifteen minutes."},{"who":"Rafael","line":"The racecourse. That's really useful."},{"who":"Imogen","line":"And one last thing: if it rains, the aquarium is a good plan B, but book online, because it gets packed."},{"who":"Rafael","line":"Imogen, you're a star. I'll send you a postcard."},{"who":"Imogen","line":"Send me a photo of Bea with a kite instead!"}],"notes":{"title":"Family weekend in the city","headings":["Where to stay","Getting around","Saturday","Sunday"]},"groups":[{"instruction":"Questions 1-10. Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","qtype":"note","questions":[{"n":1,"kind":"gap","prompt":"Where to stay · holiday flats next to the ___","accept":["canal"],"limit":1,"evidence":"holiday flats right beside the canal","why":{"en":"\"Right beside the canal\" = next to the canal.","tr":"\"Kanalın hemen yanında\" = next to the canal.","fa":"«درست کنار کانال» یعنی next to the canal."},"trap":["TR-paraphrase"]},{"n":2,"kind":"gap","prompt":"Where to stay · cost: £___ per night","accept":["145"],"limit":1,"evidence":"It's a hundred and forty-five now","why":{"en":"160 was the spring price. \"They’ve brought it down\": 145 now. The hotels (over 200) are a distractor.","tr":"160 bahar fiyatıydı. \"İndirdiler\": artık 145. Oteller (200’ün üstü) çeldirici.","fa":"۱۶۰ قیمت بهار بود. «پایینش آورده‌اند»: الان ۱۴۵. هتل‌ها (بیش از ۲۰۰) گزینه‌ی انحرافی‌اند."},"trap":["TR-price","TR-selfcorrect"]},{"n":3,"kind":"gap","prompt":"Getting around · buy a family ___ for the buses","accept":["pass"],"limit":1,"evidence":"Get a family pass for the buses","why":{"en":"\"Get a family pass\", and it covers the whole weekend.","tr":"\"Bir aile kartı al\", bütün hafta sonunu kapsıyor.","fa":"«یک کارت خانوادگی بگیر» که کل آخر هفته را پوشش می‌دهد."},"trap":["TR-paraphrase"]},{"n":4,"kind":"gap","prompt":"Saturday · walking tour: lasts ___ minutes","accept":["90"],"limit":1,"evidence":"It's ninety minutes","why":{"en":"Rafael hears \"nineteen\", and Imogen repeats it another way: \"nine-zero, an hour and a half\".","tr":"Rafael \"nineteen\" duyuyor; Imogen başka bir şekilde tekrar ediyor: \"nine-zero, bir buçuk saat\".","fa":"رافائل «nineteen» می‌شنود و ایموجن جور دیگری تکرارش می‌کند: «nine-zero، یک ساعت و نیم»."},"trap":["TR-number"]},{"n":5,"kind":"gap","prompt":"Saturday · ask for the guide called Hal ___","accept":["Treharne"],"limit":1,"evidence":"T-R-E-H-A-R-N-E","why":{"en":"Spelled T-R-E-H-A-R-N-E. Every letter must match, with the capital T.","tr":"T-R-E-H-A-R-N-E diye harf harf söyleniyor. Her harf aynı olmalı, baştaki T büyük.","fa":"حرف به حرف: T-R-E-H-A-R-N-E. همه‌ی حرف‌ها باید درست باشند، با T بزرگ اول."},"trap":["TR-spell"]},{"n":6,"kind":"gap","prompt":"Saturday · Museum of Childhood: family workshop starts at ___ pm","accept":["3.30","3:30"],"limit":1,"evidence":"In summer and autumn it's half past three","why":{"en":"Two o’clock is the winter timetable on the website. For their trip: half past three, written 3.30.","tr":"Saat iki web sitesindeki kış programı. Onların gezisi için: üç buçuk, yani 3.30.","fa":"ساعت دو برنامه‌ی زمستانیِ سایت است. برای سفر آن‌ها: سه و نیم، یعنی ۳:۳۰."},"trap":["TR-selfcorrect"]},{"n":7,"kind":"gap","prompt":"Sunday · food market in an old bus ___","accept":["garage"],"limit":1,"evidence":"in an old bus garage","why":{"en":"\"An old bus garage near the river\". \"bus\" is printed, so write one word.","tr":"\"Nehrin yakınında eski bir otobüs garajı\". \"bus\" yazılı, tek kelime yaz.","fa":"«یک گاراژ قدیمی اتوبوس نزدیک رودخانه». «bus» چاپ شده، پس یک کلمه بنویس."},"trap":["TR-paraphrase"]},{"n":8,"kind":"gap","prompt":"Sunday · the stall the children will like best sells ___","accept":["dumplings"],"limit":1,"evidence":"the one selling dumplings","why":{"en":"The pizza van is \"nothing special\". The stall the children will love sells dumplings. Keep the plural.","tr":"Pizza arabası \"özel bir şey değil\". Çocukların seveceği tezgâh mantı satıyor. Çoğulu koru.","fa":"ون پیتزا «چیز خاصی نیست». غرفه‌ای که بچه‌ها دوستش دارند دامپلینگ می‌فروشد. جمع را نگه دار."},"trap":["TR-paraphrase"]},{"n":9,"kind":"gap","prompt":"Sunday · kite festival: kites can be borrowed, but take a ___","accept":["blanket"],"limit":1,"evidence":"do bring a blanket","why":{"en":"Kites are lent at the gate. \"Do bring a blanket\", because the grass is damp.","tr":"Uçurtmalar kapıda ödünç veriliyor. \"Mutlaka bir battaniye getirin\", çünkü çimen nemli.","fa":"بادبادک را دمِ در قرض می‌دهند. «حتماً یک پتو بیاور»، چون چمن نمناک است."},"trap":["TR-paraphrase"]},{"n":10,"kind":"gap","prompt":"Sunday · parking: leave the car at the ___ (free on Sundays)","accept":["racecourse"],"limit":1,"evidence":"leave the car at the racecourse","why":{"en":"The park’s own car park fills up. \"Leave the car at the racecourse.\"","tr":"Parkın kendi otoparkı doluyor. \"Arabayı hipodromda bırak.\"","fa":"پارکینگ خودِ پارک پر می‌شود. «ماشین را در میدان اسب‌دوانی بگذار»."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Imogen":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_lily"},"role":"Friend who lives in the city"},"Rafael":{"accent":"North American","gender":"M","tts":{"engine":"kokoro","voice":"am_michael"},"role":"Friend planning a family weekend"}},"sequence":[{"type":"announcer","text":"Part 1. You will hear a woman giving a friend advice about a family weekend in the city. First, you have some time to look at Questions 1 to 6."},{"type":"pause","seconds":30,"note":"reading time, Questions 1-6"},{"type":"announcer","text":"Now listen carefully and answer Questions 1 to 6."},{"type":"lines","from":0,"to":20,"note":"phone line: light telephone filter on Rafael only; a ring before line 0"},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 7 to 10."},{"type":"pause","seconds":30,"note":"reading time, Questions 7-10"},{"type":"announcer","text":"Now listen and answer Questions 7 to 10."},{"type":"lines","from":21,"to":32},{"type":"announcer","text":"That is the end of Part 1. You now have half a minute to check your answers.","after":30}]},"id":"c-x08-l1-d","course":"ielts-exams","exam":"exam-08","unit":"x08-l1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"A friend says the market gets \"packed\" by eleven. This means it is...","options":["very crowded","closed","sold out of food"],"correct":0,"why":{"en":"Packed = full of people, very crowded.","tr":"Packed = insanla dolu, çok kalabalık.","fa":"packed یعنی پر از آدم، خیلی شلوغ."}},{"tests":"paraphrase","point":1,"prompt":"The notes say \"free on Sundays\". Which words in a recording could you hear instead?","options":["it’s cheaper on Sundays","it’s open on Sundays","there’s no charge on Sundays"],"correct":2,"why":{"en":"\"No charge\" = free. Cheaper still costs money; open says nothing about the price.","tr":"\"No charge\" = ücretsiz. Daha ucuz yine de para demek; açık olması fiyat hakkında bir şey söylemez.","fa":"«no charge» یعنی رایگان. ارزان‌تر هنوز پول دارد؛ باز بودن هم چیزی درباره‌ی قیمت نمی‌گوید."}},{"tests":"trap","point":3,"prompt":"Gap: \"Bike hire: £___ a day\". You hear: \"It’s thirteen a day. No, wait, thirty. Thirteen is for children.\" What do you write?","options":["13","30","43"],"correct":1,"why":{"en":"The speaker corrects the price for adults: thirty. Thirteen is the children’s price.","tr":"Konuşan yetişkin fiyatını düzeltiyor: otuz. On üç çocuk fiyatı.","fa":"گوینده قیمتِ بزرگسال را اصلاح می‌کند: سی. سیزده قیمت بچه‌هاست."}},{"tests":"method","point":2,"prompt":"You have not heard the answer to Question 3, but the speakers are now talking about Saturday. What do you do?","options":["Leave 3 and listen for the Saturday notes","Wait on Question 3 until you hear it","Write the last word you heard for 3"],"correct":0,"why":{"en":"The heading tells you the speakers have moved on. Follow them and guess 3 at the end.","tr":"Başlık konuşanların ilerlediğini söylüyor. Onları takip et, 3’ü sonda tahmin et.","fa":"عنوان می‌گوید گوینده‌ها جلو رفته‌اند. دنبالشان برو و ۳ را آخر کار حدس بزن."}},{"tests":"method","point":2,"prompt":"A name is spelled: \"M-c-C-A-L-L\". How do you write it?","options":["Mccall","Mc Call","McCall"],"correct":2,"why":{"en":"Copy every letter as it is spelled, with the capitals: McCall.","tr":"Her harfi söylendiği gibi büyük harfleriyle kopyala: McCall.","fa":"همه‌ی حرف‌ها را همان‌طور که هجی می‌شوند، با حرف‌های بزرگ بنویس: McCall."}}],"id":"c-x08-l1-x","course":"ielts-exams","exam":"exam-08","unit":"x08-l1"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
